/**
 * Cloudflare Worker entry point. It wraps the OpenNext handler for the
 * Next.js app and adds what Next.js cannot declare itself: the bulk email
 * queue Durable Object and the daily storage cleanup cron.
 */
// @ts-ignore The OpenNext build output is generated by `opennextjs-cloudflare build`.
import { default as nextHandler } from './.open-next/worker.js';
import { EmailQueueObject } from './lib/email/queue-object';
import { CLEANUP_KEY_HEADER } from './lib/storage/cleanup-handler';
import type { ExecutionContext, ScheduledController } from './lib/cloudflare/types';

interface WorkerEnv {
  CLEANUP_SECRET_KEY?: string;
  [binding: string]: unknown;
}

type NextFetch = (request: Request, env: WorkerEnv, ctx: ExecutionContext) => Promise<Response>;

export default {
  fetch(request: Request, env: WorkerEnv, ctx: ExecutionContext): Promise<Response> {
    return (nextHandler.fetch as NextFetch)(request, env, ctx);
  },

  // Deletes expired files from R2 through the existing cleanup route, so the
  // rules stay in one place and the route's secret check still applies.
  async scheduled(_controller: ScheduledController, env: WorkerEnv, ctx: ExecutionContext): Promise<void> {
    if (!env.CLEANUP_SECRET_KEY) {
      console.error('Skipping storage cleanup: CLEANUP_SECRET_KEY is not set');
      return;
    }
    const request = new Request('https://internal/api/cleanup-r2', {
      method: 'POST',
      headers: { [CLEANUP_KEY_HEADER]: env.CLEANUP_SECRET_KEY }
    });
    const response = await (nextHandler.fetch as NextFetch)(request, env, ctx);
    const body = await response.text();
    if (!response.ok) {
      console.error(`Storage cleanup failed with ${response.status}: ${body.slice(0, 500)}`);
      return;
    }
    console.log(`Storage cleanup finished: ${body.slice(0, 500)}`);
  }
};

export { EmailQueueObject };
// Durable Objects used by OpenNext's caching, re-exported as its docs require.
// @ts-ignore The OpenNext build output is generated by `opennextjs-cloudflare build`.
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from './.open-next/worker.js';
